/**
 * /media-coverage/
 *
 * NO `// GENERATED by scripts/gen-pages.mjs` MARKER, deliberately.
 * gen-pages.mjs overwrites any page file whose content starts with that line,
 * so leaving it here would mean the next `npm run gen:pages` silently destroys
 * this page. Removing it is what puts the file on the script's `kept:` list.
 * Same call, for the same reason, as image-gallery.tsx and home.tsx.
 *
 * PagePlaceholder is not used either: it renders `seoFor(slug).h1`, which would
 * be a SECOND <h1> under the one PageBanner already emits.
 *
 * This page postdates the WordPress capture, so its SEO record and JSON-LD are
 * authored in content/seo/media-coverage.json and picked up by
 * `npm run gen:seo` -- the route dutexome-hair-treatment-in-bangalore
 * established. There is no row for it in 01-SEO-MASTER.csv and there should
 * not be.
 */
import MediaCoveragePage from '../components/MediaCoveragePage'

export default function MediaCoverage() {
  return <MediaCoveragePage />
}
